package com.osrslootsim;

import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import javax.swing.Icon;

/**
 * A small cog, for the button that opens the plugin's settings.
 */
final class Cog implements Icon
{
	private static final int SIZE = 14;
	private static final Shape SHAPE = shape();

	private final Color colour;

	Cog(Color colour)
	{
		this.colour = colour;
	}

	@Override
	public void paintIcon(Component c, Graphics g, int x, int y)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.translate(x + SIZE / 2.0, y + SIZE / 2.0);
		g2.setColor(colour);
		g2.fill(SHAPE);
		g2.dispose();
	}

	@Override
	public int getIconWidth()
	{
		return SIZE;
	}

	@Override
	public int getIconHeight()
	{
		return SIZE;
	}

	// Eight teeth round a wheel with a hole through its middle, drawn around 0, 0
	private static Shape shape()
	{
		Path2D cog = new Path2D.Double(Path2D.WIND_EVEN_ODD);
		int teeth = 8;
		for (int tooth = 0; tooth < teeth; tooth++)
		{
			double middle = tooth * 2 * Math.PI / teeth;
			// a tooth's two feet on the wheel and its two tips: an angle and how far out
			double[][] corners = {{middle - 0.28, 4.6}, {middle - 0.17, 6.7}, {middle + 0.17, 6.7}, {middle + 0.28, 4.6}};
			for (double[] corner : corners)
			{
				double x = Math.cos(corner[0]) * corner[1];
				double y = Math.sin(corner[0]) * corner[1];
				if (cog.getCurrentPoint() == null)
				{
					cog.moveTo(x, y);
				}
				else
				{
					cog.lineTo(x, y);
				}
			}
		}
		cog.closePath();
		cog.append(new Ellipse2D.Double(-2.1, -2.1, 4.2, 4.2), false);
		return cog;
	}
}

package com.osrslootsim;

import javax.swing.text.AttributeSet;
import javax.swing.text.BadLocationException;
import javax.swing.text.DocumentFilter;

/**
 * Lets only digits into a text box, up to a length.
 */
final class DigitsOnly extends DocumentFilter
{
	private final int max;

	DigitsOnly(int max)
	{
		this.max = max;
	}

	@Override
	public void insertString(FilterBypass fb, int offset, String text, AttributeSet attr) throws BadLocationException
	{
		replace(fb, offset, 0, text, attr);
	}

	@Override
	public void replace(FilterBypass fb, int offset, int length, String text, AttributeSet attr) throws BadLocationException
	{
		String digits = text == null ? "" : text.replaceAll("[^0-9]", "");
		int room = max - (fb.getDocument().getLength() - length);
		if (room <= 0 && !digits.isEmpty())
		{
			return;
		}
		super.replace(fb, offset, length, digits.length() > room ? digits.substring(0, Math.max(0, room)) : digits, attr);
	}
}

package com.osrslootsim;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.font.TextAttribute;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.client.ui.FontManager;

/**
 * Draws the pop-up card, in the look of osrslootsim.com's own celebration: charcoal with a brass frame, a title in
 * orange capitals, the item and its name. An insane drop in a simulated run gets one, and so can a new collection
 * log item in the game. The burst of light and the loot beam are Burst's.
 */
final class DropCard
{
	// The card's size before the player resizes it, and how far it can be shrunk and grown from that. A card with a
	// line over the item's name is that line taller.
	static final int WIDTH = 190;
	static final int HEIGHT = 128;
	private static final int LEAD_HEIGHT = 12;
	static final float SMALLEST = 0.6f;
	static final float LARGEST = 3f;

	private static final Color TIER = new Color(0xFF, 0x8A, 0x1F);
	private static final Color BODY = new Color(27, 26, 23, 240);
	private static final Color FRAME = new Color(206, 122, 44);
	private static final Color BRASS = new Color(164, 138, 91, 102);
	private static final Color UNLOCKED = new Color(0, 230, 255);
	private static final int TITLE_SIZE = 19;
	private static final int SMALLEST_TITLE = 12;
	private static final Font NAME = FontManager.getRunescapeBoldFont();
	private static final Font SMALL = FontManager.getRunescapeSmallFont();
	// The title's font for each kind of card, made the first time it is drawn: the largest that fits the card
	private static final Map<Kind, Font> TITLE_FONTS = new EnumMap<>(Kind.class);

	/**
	 * What a card is for, which words its title and the line over the item's name.
	 */
	enum Kind
	{
		INSANE("INSANE DROP!", null),
		// As the game's own pop-up words it
		COLLECTION_LOG("COLLECTION LOG", "New item:");

		private final String title;
		private final String lead;
		private final int height;

		Kind(String title, String lead)
		{
			this.title = title;
			this.lead = lead;
			this.height = HEIGHT + (lead == null ? 0 : LEAD_HEIGHT);
		}
	}

	/**
	 * What a card shows. The picture may arrive after the card is up.
	 */
	static final class Drop
	{
		final Kind kind;
		final String name;
		volatile BufferedImage picture;

		Drop(Kind kind, String name)
		{
			this.kind = kind;
			this.name = name;
		}
	}

	private DropCard()
	{
	}

	/**
	 * The size of the card that fits in a space, keeping its shape: 1 is its own size.
	 */
	static float scale(int width, int height)
	{
		return Math.max(SMALLEST, Math.min(LARGEST, Math.min(width / (float) WIDTH, height / (float) HEIGHT)));
	}

	/**
	 * How much of the screen a kind of card covers at a size.
	 */
	static Dimension size(Kind kind, float scale)
	{
		return new Dimension(Math.round(WIDTH * scale), Math.round(kind.height * scale));
	}

	/**
	 * The card, its top left corner at x, y. scale is its size (1 is its own); opacity runs from 0 to 1, for fading
	 * in and out.
	 */
	static void paintCard(Graphics2D graphics, int x, int y, float scale, Drop drop, float opacity)
	{
		Graphics2D g = begin(graphics, opacity);
		g.translate(x, y);
		g.scale(scale, scale);
		int w = WIDTH;
		int h = drop.kind.height;
		int centre = w / 2;
		for (int i = 1; i <= 8; i++)
		{
			g.setColor(new Color(255, 138, 31, 27 - 3 * i));
			g.drawRect(-i, -i, w + 2 * i - 1, h + 2 * i - 1);
		}
		g.setColor(BODY);
		g.fillRect(0, 0, w, h);
		g.setColor(new Color(15, 14, 12));
		g.drawRect(-1, -1, w + 1, h + 1);
		g.setColor(FRAME);
		g.drawRect(0, 0, w - 1, h - 1);
		g.setColor(new Color(17, 15, 13));
		g.drawRect(1, 1, w - 3, h - 3);
		g.setColor(BRASS);
		g.drawRect(2, 2, w - 5, h - 5);

		String title = drop.kind.title;
		g.setFont(titleFont(g, drop.kind));
		int left = centre - g.getFontMetrics().stringWidth(title) / 2;
		int baseline = 8 + 18;
		g.setColor(new Color(255, 138, 31, 60));
		for (int[] off : new int[][]{{-2, 0}, {2, 0}, {0, -2}, {0, 2}, {-1, -1}, {1, 1}, {-1, 1}, {1, -1}})
		{
			g.drawString(title, left + off[0], baseline + off[1]);
		}
		g.setColor(Color.BLACK);
		g.drawString(title, left + 2, baseline + 2);
		g.setColor(TIER);
		g.drawString(title, left, baseline);

		int rule = 8 + 22 + 4;
		g.setPaint(new GradientPaint(22, rule, new Color(255, 138, 31, 0), centre, rule, new Color(255, 138, 31, 204), true));
		g.fillRect(22, rule, w - 44, 1);

		int middle = rule + 1 + 3 + 32;
		g.setPaint(new RadialGradientPaint(centre, middle, 44, new float[]{0f, 0.55f, 1f},
			new Color[]{new Color(255, 242, 173, 102), new Color(255, 210, 125, 40), new Color(255, 210, 125, 0)}));
		g.fillOval(centre - 44, middle - 44, 88, 88);
		BufferedImage picture = drop.picture;
		if (picture != null)
		{
			// Inventory sprites are small pixel pictures: drawn at a whole number of times their size, twice on a card
			// of its own size, so every pixel stays a square however the card is sized
			int times = Math.max(1, Math.round(2 * scale));
			Graphics2D p = begin(graphics, opacity);
			p.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			p.drawImage(picture, x + Math.round(centre * scale) - picture.getWidth() * times / 2, y + Math.round(middle * scale) - picture.getHeight() * times / 2,
				picture.getWidth() * times, picture.getHeight() * times, null);
			p.dispose();
		}

		int nameBase = h - 8 - 3;
		if (drop.kind.lead != null)
		{
			g.setFont(SMALL);
			centred(g, drop.kind.lead, centre, nameBase - 14, TIER);
		}
		g.setFont(NAME);
		centred(g, fit(g.getFontMetrics(), drop.name, w - 20), centre, nameBase, Color.WHITE);
		g.dispose();
	}

	/**
	 * Marks a card that is unlocked, over a card of the given size drawn at x, y: a bright edge, and how to move it
	 * in a strip over the card. toLeft and above are how much of the screen there is on those sides of the card: the
	 * strip goes under a card too near the top for it, and stops at the screen's left edge.
	 */
	static void paintUnlocked(Graphics2D graphics, int x, int y, Dimension size, String[] lines, int toLeft, int above)
	{
		Graphics2D g = begin(graphics, 1f);
		g.translate(x, y);
		int w = size.width;
		int h = size.height;
		g.setColor(new Color(UNLOCKED.getRed(), UNLOCKED.getGreen(), UNLOCKED.getBlue(), 26));
		g.fillRect(0, 0, w, h);
		g.setColor(UNLOCKED);
		g.setStroke(new BasicStroke(2f));
		g.drawRect(-2, -2, w + 3, h + 3);

		g.setFont(SMALL);
		FontMetrics metrics = g.getFontMetrics();
		int widest = 0;
		for (String line : lines)
		{
			widest = Math.max(widest, metrics.stringWidth(line));
		}
		int step = metrics.getHeight();
		int stripWidth = widest + 12;
		int stripHeight = step * lines.length + 6;
		int stripX = Math.max(2 - toLeft, (w - stripWidth) / 2);
		int stripY = above < stripHeight + 8 ? h + 8 : -8 - stripHeight;
		g.setColor(new Color(15, 14, 12, 225));
		g.fillRect(stripX, stripY, stripWidth, stripHeight);
		g.setColor(UNLOCKED);
		g.setStroke(new BasicStroke(1f));
		g.drawRect(stripX, stripY, stripWidth - 1, stripHeight - 1);
		for (int i = 0; i < lines.length; i++)
		{
			centred(g, lines[i], stripX + stripWidth / 2, stripY + 3 + metrics.getAscent() + step * i, Color.WHITE);
		}
		g.dispose();
	}

	/**
	 * A copy of a drawing surface to draw something on at an opacity from 0 to 1, with smooth edges switched on.
	 */
	static Graphics2D begin(Graphics2D graphics, float opacity)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Composite now = g.getComposite();
		float held = now instanceof AlphaComposite ? ((AlphaComposite) now).getAlpha() : 1f;
		g.setComposite(AlphaComposite.SrcOver.derive(Math.max(0f, Math.min(1f, held * opacity))));
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		return g;
	}

	// A line of text with its middle at centre, over its own shadow
	private static void centred(Graphics2D g, String text, int centre, int baseline, Color colour)
	{
		int left = centre - g.getFontMetrics().stringWidth(text) / 2;
		g.setColor(Color.BLACK);
		g.drawString(text, left + 1, baseline + 1);
		g.setColor(colour);
		g.drawString(text, left, baseline);
	}

	private static String fit(FontMetrics metrics, String text, int room)
	{
		if (metrics.stringWidth(text) <= room)
		{
			return text;
		}
		String cut = text;
		while (cut.length() > 1 && metrics.stringWidth(cut + "...") > room)
		{
			cut = cut.substring(0, cut.length() - 1);
		}
		return cut + "...";
	}

	// A longer title than "INSANE DROP!" is set smaller, to stay inside the frame
	private static Font titleFont(Graphics2D g, Kind kind)
	{
		Font font = TITLE_FONTS.get(kind);
		if (font == null)
		{
			int size = TITLE_SIZE;
			font = capitals(size, 0.06f);
			while (size > SMALLEST_TITLE && g.getFontMetrics(font).stringWidth(kind.title) > WIDTH - 22)
			{
				font = capitals(--size, 0.06f);
			}
			TITLE_FONTS.put(kind, font);
		}
		return font;
	}

	// The site sets the tier in Palatino capitals; any serif stands in where that font is missing
	private static Font capitals(int size, float tracking)
	{
		Font font = new Font("Palatino Linotype", Font.BOLD, size);
		if (!"Palatino Linotype".equalsIgnoreCase(font.getFamily()))
		{
			font = new Font(Font.SERIF, Font.BOLD, size);
		}
		return font.deriveFont(Collections.singletonMap(TextAttribute.TRACKING, tracking));
	}
}

package com.osrslootsim;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.io.IOException;
import java.time.LocalDate;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.UnsupportedAudioFileException;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.ItemLayer;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Renderable;
import net.runelite.api.Tile;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The plugin's celebrations. An insane drop in a simulated run gets a pop-up card with the item, a burst of light
 * with a loot beam on the floor under the player's character, and the site's pet fanfare. The burst can also mark a
 * level gained, a new collection log item or valuable loot in the game itself, and a new collection log item can
 * have the card too. Each part has its own switch in the plugin's settings, and everything goes by itself after a
 * few seconds. The card starts in the chatbox and can be moved and resized like RuneLite's own overlays.
 */
final class DropPopups
{
	// As long as osrslootsim.com shows an insane drop
	private static final int SHOWN_MS = 4800;
	private static final int FADE_IN_MS = 150;
	private static final int FADE_OUT_MS = 400;
	// Two reports of one event (a chat line and a pop-up for the same collection log item) are one burst
	private static final int SAME_EVENT_MS = 1500;
	private static final String INSANE = "insane";
	// The item on the card that is shown while the card is unlocked
	private static final String SAMPLE_NAME = "Twisted bow";
	// How far around the character to look for things standing in front of the burst, in tiles
	private static final int AROUND = 6;
	// How far from where it stands a thing is taken to reach at most, in the game's units (128 to a tile)
	private static final int THING_REACH = 448;
	// A model that rises less than this off the floor is part of the floor (a rug, a marking), and the burst lies on it
	private static final int FLOOR_THICK = 24;
	// How much nearer to the camera than the character something must stand to hide the beam
	private static final int NEARER_BY = 40;

	private final Client client;
	private final ClientThread clientThread;
	private final LootSimConfig config;
	private final Icons icons;
	private final OverlayManager overlayManager;
	private final AudioPlayer audioPlayer;
	private final RuneLiteConfig runeLiteConfig;
	private final Overlay card = new Card();
	private final Overlay burst = new CharacterBurst();

	// Set when something happens (a run arriving on the Swing thread, a game event on the game's thread), read on the
	// game's thread every frame
	private volatile DropCard.Drop drop;
	private volatile long cardAt;
	// What an unlocked card shows; made the first time it is needed, on the game's thread
	private DropCard.Drop sample;
	private volatile long burstAt;
	// The holiday the burst is dressed for, settled when it starts
	private volatile Season burstSeason = Season.NONE;
	private volatile Burst.Glow burstGlow = Burst.Glow.GOLD;

	DropPopups(Client client, ClientThread clientThread, LootSimConfig config, Icons icons, OverlayManager overlayManager, AudioPlayer audioPlayer,
		RuneLiteConfig runeLiteConfig)
	{
		this.runeLiteConfig = runeLiteConfig;
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.icons = icons;
		this.overlayManager = overlayManager;
		this.audioPlayer = audioPlayer;
	}

	void start()
	{
		overlayManager.add(card);
		overlayManager.add(burst);
	}

	void stop()
	{
		overlayManager.remove(card);
		overlayManager.remove(burst);
		drop = null;
		burstAt = 0;
		// The burst's sheets belong to the game's thread, which may be drawing on them right now
		clientThread.invokeLater(Burst::release);
	}

	/**
	 * A run arrived: celebrates its best insane drop, if it has one, with whichever of the card, the burst and the
	 * sound are switched on. The site marks which drops are insane, by its own rule: a collection log item rarer
	 * than 1/2,000, or anything worth 10m or more apiece.
	 */
	void ran(LootSimApi.Run run)
	{
		LootSimApi.Item best = null;
		for (LootSimApi.Item item : run.items)
		{
			if (INSANE.equals(item.tier) && (best == null || each(item) > each(best)))
			{
				best = item;
			}
		}
		if (best == null)
		{
			return;
		}
		if (config.insaneDropCard())
		{
			show(DropCard.Kind.INSANE, best.id, Text.plain(best.name, 40));
		}
		if (config.insaneDropBurst())
		{
			burst();
		}
		if (config.insaneDropSound())
		{
			fanfare();
		}
	}

	/**
	 * The game added an item to the collection log: shows the card and the burst, whichever are switched on for that.
	 */
	void collected(String item)
	{
		String name = Text.plain(item, 40);
		if (config.collectionLogCard() && !name.isEmpty())
		{
			show(DropCard.Kind.COLLECTION_LOG, 0, name);
		}
		if (config.collectionLogBeam())
		{
			burst();
		}
	}

	/**
	 * Puts a card up. The same card again while it is up (the game's chat line and, some time later, its pop-up for
	 * one item) is the card that is already there.
	 */
	private void show(DropCard.Kind kind, int id, String name)
	{
		long now = System.currentTimeMillis();
		DropCard.Drop up = drop;
		if (up != null && up.kind == kind && up.name.equals(name) && now - cardAt < SHOWN_MS)
		{
			return;
		}
		DropCard.Drop shown = new DropCard.Drop(kind, name);
		icons.picture(id, name, picture -> shown.picture = picture);
		cardAt = now;
		drop = shown;
	}

	/**
	 * Starts the burst on the character. Called for an insane drop, and for a level, a collection log item or valuable
	 * loot gained in the game when those switches are on.
	 */
	void burst()
	{
		long now = System.currentTimeMillis();
		if (now - burstAt > SAME_EVENT_MS)
		{
			burstSeason = config.holidayLook().season(LocalDate.now());
			burstGlow = config.beamColour().glow(burstSeason);
			burstAt = now;
		}
	}

	/**
	 * Plays the site's pet fanfare, the holiday's own in season, at the volume the settings give.
	 */
	private void fanfare()
	{
		int volume = Math.max(0, Math.min(100, config.soundVolume()));
		if (volume == 0)
		{
			return;
		}
		Season season = config.holidayLook().season(LocalDate.now());
		// The player takes a gain in decibels: every halving of the volume is 6 less
		float gain = (float) (20 * Math.log10(volume / 100.0));
		try
		{
			audioPlayer.play(DropPopups.class, season.fanfare(), gain);
		}
		catch (IOException | UnsupportedAudioFileException | LineUnavailableException | IllegalArgumentException e)
		{
			// no sound device, or one that will not take the format: the card and the burst still show
		}
	}

	private static long each(LootSimApi.Item item)
	{
		return item.value / Math.max(1, item.qty);
	}

	/**
	 * How solid something that began at the given time is right now, from 0 to 1; 0 once its time is up.
	 */
	private static float opacity(long began)
	{
		long age = System.currentTimeMillis() - began;
		if (age < 0 || age >= SHOWN_MS)
		{
			return 0;
		}
		if (age < FADE_IN_MS)
		{
			return (float) age / FADE_IN_MS;
		}
		return age > SHOWN_MS - FADE_OUT_MS ? (float) (SHOWN_MS - age) / FADE_OUT_MS : 1f;
	}

	/**
	 * The card. It is one of RuneLite's movable overlays: with the drag key held (Alt, unless the player changed it)
	 * it is dragged, resized by its edges and put back with a right-click, and RuneLite keeps where it was put. Until
	 * the player moves it, it stands in the chatbox. With "Lock pop-up" unticked it stays on screen, marked, with a
	 * sample item, so there is something to drag.
	 */
	private final class Card extends Overlay
	{
		// For a card the player has not placed: where it was last told to stand, and where RuneLite then stood it
		// (the same place, unless that was partly off the screen)
		private java.awt.Point told;
		private java.awt.Point stood;

		Card()
		{
			setPosition(OverlayPosition.DYNAMIC);   // which also says it stays put: movable is switched on after it
			setLayer(OverlayLayer.ABOVE_WIDGETS);
			setPriority(PRIORITY_HIGH);
			setMovable(true);
			setResizable(true);
			setMinimumSize(Math.round(DropCard.HEIGHT * DropCard.SMALLEST));
		}

		// RuneLite keeps an overlay's place under this name, which is the class's own unless told otherwise
		@Override
		public String getName()
		{
			return "OsrsLootSimCard";
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			boolean unlocked = !config.lockCard();
			DropCard.Drop shown = unlocked ? sample() : drop;
			float opacity = unlocked ? 1f : opacity(cardAt);
			if (shown == null || opacity <= 0)
			{
				drop = null;
				return null;
			}
			Dimension room = getPreferredSize();
			float scale = room == null ? 1f : DropCard.scale(room.width, room.height);
			Dimension size = DropCard.size(shown.kind, scale);
			if (!inPlace(size))
			{
				return size;   // RuneLite drew this frame somewhere else: the card is there from the next one
			}
			DropCard.paintCard(graphics, 0, 0, scale, shown, opacity);
			if (unlocked)
			{
				String key = String.valueOf(runeLiteConfig.dragHotkey());
				String[] how = {"Hold " + key + ", then", "drag to move, drag an edge to resize,", "right-click to put it back"};
				DropCard.paintUnlocked(graphics, 0, 0, size, how, getBounds().x, getBounds().y);
			}
			return size;
		}

		/**
		 * Sees to it that a card the player has not placed stands in the chatbox: on the left, its bottom edge just
		 * inside the chatbox's own, or in the bottom left corner of the game when there is no chatbox to sit in (the
		 * login screen, a chatbox that is hidden). RuneLite draws an overlay like this one where it last was, so
		 * the card is moved there for the next frame. False when this frame is not there yet.
		 */
		private boolean inPlace(Dimension size)
		{
			if (getPreferredLocation() != null)
			{
				told = null;
				return true;   // the player placed it: RuneLite draws it there
			}
			Widget chat = client.getWidget(InterfaceID.Chatbox.CHATAREA);
			Rectangle area = chat == null || chat.isHidden() ? null : chat.getBounds();
			int x = area == null ? 8 : area.x + 6;
			int y = (area == null ? client.getCanvasHeight() - 30 : area.y + area.height - 6) - size.height;
			java.awt.Point wanted = new java.awt.Point(x, Math.max(2, y));
			java.awt.Point now = getBounds().getLocation();
			if (wanted.equals(told) && (stood == null || stood.equals(now)))
			{
				stood = now;
				return true;
			}
			told = wanted;
			stood = null;
			getBounds().setLocation(wanted);
			return false;
		}

		private DropCard.Drop sample()
		{
			if (sample == null)
			{
				DropCard.Drop made = new DropCard.Drop(DropCard.Kind.INSANE, SAMPLE_NAME);
				icons.picture(ItemID.TWISTED_BOW, SAMPLE_NAME, picture -> made.picture = picture);
				sample = made;
			}
			return sample;
		}
	}

	/**
	 * The burst of light and the loot beam, in the game world: on the floor under the player's character, under
	 * everything that stands on that floor, with the beam behind the character.
	 */
	private final class CharacterBurst extends Overlay
	{
		// Where a model lands on screen, corner by corner; kept between frames to spare the garbage
		private int[] cornerX = new int[0];
		private int[] cornerY = new int[0];
		private final double[] spot = new double[2];
		// True while the burst's sheets are in use
		private boolean drawn;

		// The frame being drawn: the camera, the floor, and where the character stands on it
		private double cameraX;
		private double cameraY;
		private double cameraZ;
		private double yawSin;
		private double yawCos;
		private double pitchSin;
		private double pitchCos;
		private double scale;
		private double middleX;
		private double middleY;
		private WorldView world;
		private int plane;
		private int[][][] heights;
		private byte[][][] settings;
		private double standsX;
		private double standsY;
		private double standsZ;
		// False on a boat: its floor moves through the world, and only RuneLite's own way of placing things knows how
		private boolean plain;
		// How far in front of the camera the character is
		private double mine;

		CharacterBurst()
		{
			setPosition(OverlayPosition.DYNAMIC);
			setLayer(OverlayLayer.ABOVE_SCENE);
			// Drawn before every other plugin's marks on the scene, so the names of items on the floor, of players and
			// of monsters, and tile markers, are all on top of the burst
			setPriority(PRIORITY_LOW - 1);
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			long began = burstAt;
			float opacity = opacity(began);
			if (opacity <= 0)
			{
				if (drawn)
				{
					drawn = false;
					Burst.release();
				}
				return null;
			}
			Player me = client.getLocalPlayer();
			LocalPoint at = me == null ? null : me.getLocalLocation();
			WorldView around = me == null ? null : me.getWorldView();
			if (at == null || around == null)
			{
				return null;   // no character on screen (the login screen): nothing to burst from
			}
			look(around, at);
			Rectangle view = new Rectangle(client.getViewportXOffset(), client.getViewportYOffset(), client.getViewportWidth(), client.getViewportHeight());
			drawn = true;
			Burst.paint(graphics, view, this::floor, System.currentTimeMillis() - began, opacity, burstSeason, burstGlow, cut -> infront(cut, me));
			world = null;
			heights = null;
			settings = null;
			return null;
		}

		/**
		 * Takes down what this frame is drawn with. With the GPU renderer the camera has fractional values, which is
		 * what the picture is drawn with; without it the camera moves in the game's own steps (2048 to a full turn).
		 */
		private void look(WorldView around, LocalPoint at)
		{
			double pitch;
			double yaw;
			if (client.isGpu())
			{
				pitch = client.getCameraFpPitch();
				yaw = client.getCameraFpYaw();
				cameraX = client.getCameraFpX();
				cameraY = client.getCameraFpY();
				cameraZ = client.getCameraFpZ();
			}
			else
			{
				pitch = client.getCameraPitch() * Perspective.UNIT;
				yaw = client.getCameraYaw() * Perspective.UNIT;
				cameraX = client.getCameraX();
				cameraY = client.getCameraY();
				cameraZ = client.getCameraZ();
			}
			yawSin = Math.sin(yaw);
			yawCos = Math.cos(yaw);
			pitchSin = Math.sin(pitch);
			pitchCos = Math.cos(pitch);
			scale = client.getScale();
			middleX = client.getViewportWidth() / 2.0 + client.getViewportXOffset();
			middleY = client.getViewportHeight() / 2.0 + client.getViewportYOffset();
			world = around;
			plane = around.getPlane();
			heights = around.getTileHeights();
			settings = around.getTileSettings();
			plain = around.isTopLevel() && heights != null && settings != null;
			standsX = at.getX();
			standsY = at.getY();
			standsZ = Perspective.getTileHeight(client, at, plane);
			mine = plain ? onScreen(standsX, standsY, standsZ, spot) : -1;
		}

		/**
		 * Where a spot on the floor lands on screen, for Burst: so many tiles east and north of the character, at the
		 * height the floor has there.
		 */
		private boolean floor(double east, double north, double[] screen)
		{
			double x = standsX + east * Perspective.LOCAL_TILE_SIZE;
			double y = standsY + north * Perspective.LOCAL_TILE_SIZE;
			if (plain)
			{
				return onScreen(x, y, height(x, y), screen) > 0;
			}
			Point point = Perspective.localToCanvas(client, new LocalPoint((int) Math.round(x), (int) Math.round(y), world), plane, 0);
			if (point == null)
			{
				return false;
			}
			screen[0] = point.getX();
			screen[1] = point.getY();
			return true;
		}

		/**
		 * How high the floor is at a spot: between the heights of the four corners of its tile, as RuneLite's own
		 * Perspective.getTileHeight works it out, but without rounding. Off the map, the height under the character.
		 */
		private double height(double x, double y)
		{
			int tileX = (int) Math.floor(x / Perspective.LOCAL_TILE_SIZE);
			int tileY = (int) Math.floor(y / Perspective.LOCAL_TILE_SIZE);
			int level = plane;
			if (tileX < 0 || tileY < 0 || level < 0 || level >= heights.length || tileX + 1 >= heights[level].length || tileY + 1 >= heights[level][tileX + 1].length)
			{
				return standsZ;
			}
			// A tile on a bridge has its floor a level up
			if (level < Constants.MAX_Z - 1 && level + 1 < heights.length && settings.length > 1 && tileX < settings[1].length && tileY < settings[1][tileX].length
				&& (settings[1][tileX][tileY] & Constants.TILE_FLAG_BRIDGE) == Constants.TILE_FLAG_BRIDGE)
			{
				level++;
			}
			int[][] corner = heights[level];
			double across = x / Perspective.LOCAL_TILE_SIZE - tileX;
			double up = y / Perspective.LOCAL_TILE_SIZE - tileY;
			double south = corner[tileX][tileY] * (1 - across) + corner[tileX + 1][tileY] * across;
			double north = corner[tileX][tileY + 1] * (1 - across) + corner[tileX + 1][tileY + 1] * across;
			return south * (1 - up) + north * up;
		}

		/**
		 * Where a point of the game world lands on screen, as RuneLite's own Perspective.localToCanvas works it out but
		 * without rounding to whole pixels: a tile is only a few dozen pixels wide, so whole pixels made the circles on
		 * the floor jump from frame to frame while the camera turned. Fills screen and answers how far in front of the
		 * camera the point is; answers -1, leaving screen alone, for a point behind the camera.
		 */
		private double onScreen(double x, double y, double z, double[] screen)
		{
			x -= cameraX;
			y -= cameraY;
			z -= cameraZ;
			double across = x * yawCos + y * yawSin;
			double along = y * yawCos - x * yawSin;
			double down = z * pitchCos - along * pitchSin;
			double away = along * pitchCos + z * pitchSin;
			if (away < 50)
			{
				return -1;
			}
			screen[0] = middleX + across * scale / away;
			screen[1] = middleY + down * scale / away;
			return away;
		}

		// Whether something standing at a point is between the character and the camera
		private boolean nearer(double x, double y, double z)
		{
			if (!plain || mine < 0)
			{
				return false;
			}
			double away = onScreen(x, y, z, spot);
			return away > 0 && away < mine - NEARER_BY;
		}

		/**
		 * Wipes off the burst everything that stands in front of it: the character, other players and monsters, and on
		 * the tiles around, scenery, walls, what hangs on them, and items lying on the floor.
		 */
		private void infront(Burst.Cut cut, Player me)
		{
			actor(cut, me, true);
			for (NPC npc : world.npcs())
			{
				actor(cut, npc, false);
			}
			for (Player player : world.players())
			{
				if (player != me)
				{
					actor(cut, player, false);
				}
			}

			Tile[][][] levels = world.getScene().getTiles();
			if (levels == null || plane < 0 || plane >= levels.length || levels[plane] == null)
			{
				return;
			}
			Tile[][] tiles = levels[plane];
			int middleTileX = (int) Math.floor(standsX / Perspective.LOCAL_TILE_SIZE);
			int middleTileY = (int) Math.floor(standsY / Perspective.LOCAL_TILE_SIZE);
			int fromX = Math.max(0, middleTileX - AROUND);
			int fromY = Math.max(0, middleTileY - AROUND);
			for (int tileX = fromX; tileX <= middleTileX + AROUND && tileX < tiles.length; tileX++)
			{
				for (int tileY = fromY; tileY <= middleTileY + AROUND && tileY < tiles[tileX].length; tileY++)
				{
					Tile tile = tiles[tileX][tileY];
					if (tile != null)
					{
						tile(cut, tile, tileX, tileY, fromX, fromY);
					}
				}
			}
		}

		private void tile(Burst.Cut cut, Tile tile, int tileX, int tileY, int fromX, int fromY)
		{
			GameObject[] objects = tile.getGameObjects();
			if (objects != null)
			{
				for (GameObject object : objects)
				{
					// A player or a monster is listed among the scenery of its tile too, and has its turn by itself
					if (object == null || object.getRenderable() instanceof Actor)
					{
						continue;
					}
					// One that covers several tiles is listed on each of them: taken on the first it has among those looked at
					Point corner = object.getSceneMinLocation();
					if (corner != null && (Math.max(corner.getX(), fromX) != tileX || Math.max(corner.getY(), fromY) != tileY))
					{
						continue;
					}
					int z = object.getZ();
					thing(cut, object.getRenderable(), object.getX(), object.getY(), z, object.getModelOrientation(),
						nearer(object.getX(), object.getY(), z), false, THING_REACH + Math.max(object.sizeX(), object.sizeY()) * Perspective.LOCAL_TILE_SIZE / 2);
				}
			}

			WallObject wall = tile.getWallObject();
			if (wall != null)
			{
				// A wall stands on an edge of its tile: that edge, not the middle of the tile, says which side of the
				// character it is on
				int side = wall.getOrientationA();
				int edgeX = wall.getX() + ((side & 4) != 0 ? 60 : (side & 1) != 0 ? -60 : 0);
				int edgeY = wall.getY() + ((side & 2) != 0 ? 60 : (side & 8) != 0 ? -60 : 0);
				boolean nearer = nearer(edgeX, edgeY, wall.getZ());
				thing(cut, wall.getRenderable1(), wall.getX(), wall.getY(), wall.getZ(), 0, nearer, true, THING_REACH);
				thing(cut, wall.getRenderable2(), wall.getX(), wall.getY(), wall.getZ(), 0, nearer, true, THING_REACH);
			}

			DecorativeObject hung = tile.getDecorativeObject();
			if (hung != null)
			{
				int z = hung.getZ();
				boolean nearer = nearer(hung.getX() + hung.getXOffset(), hung.getY() + hung.getYOffset(), z);
				thing(cut, hung.getRenderable(), hung.getX() + hung.getXOffset(), hung.getY() + hung.getYOffset(), z, 0, nearer, true, THING_REACH);
				thing(cut, hung.getRenderable2(), hung.getX() + hung.getXOffset2(), hung.getY() + hung.getYOffset2(), z, 0, nearer, true, THING_REACH);
			}

			GroundObject low = tile.getGroundObject();
			if (low != null)
			{
				thing(cut, low.getRenderable(), low.getX(), low.getY(), low.getZ(), 0, nearer(low.getX(), low.getY(), low.getZ()), false, THING_REACH);
			}

			ItemLayer pile = tile.getItemLayer();
			if (pile != null)
			{
				int z = pile.getZ() - pile.getHeight();
				boolean nearer = nearer(pile.getX(), pile.getY(), z);
				thing(cut, pile.getBottom(), pile.getX(), pile.getY(), z, 0, nearer, true, THING_REACH);
				thing(cut, pile.getMiddle(), pile.getX(), pile.getY(), z, 0, nearer, true, THING_REACH);
				thing(cut, pile.getTop(), pile.getX(), pile.getY(), z, 0, nearer, true, THING_REACH);
			}
		}

		/**
		 * Wipes a player or a monster off the burst. self: the player's own character, which is always in front of the
		 * beam.
		 */
		private void actor(Burst.Cut cut, Actor actor, boolean self)
		{
			LocalPoint where = actor.getLocalLocation();
			if (where == null || Math.abs(where.getX() - standsX) > (AROUND + 2) * Perspective.LOCAL_TILE_SIZE
				|| Math.abs(where.getY() - standsY) > (AROUND + 2) * Perspective.LOCAL_TILE_SIZE)
			{
				return;
			}
			int z = Perspective.getFootprintTileHeight(client, where, plane, actor.getFootprintSize());
			thing(cut, actor, where.getX(), where.getY(), z, actor.getCurrentOrientation(), self || nearer(where.getX(), where.getY(), z), true,
				THING_REACH + actor.getFootprintSize() * Perspective.LOCAL_TILE_SIZE / 2);
		}

		/**
		 * Wipes one thing off the burst, face by face of its model, placed the way RuneLite's own outline drawing
		 * places it. x, y, z: where it stands. nearer: whether it is between the character and the camera. lowToo:
		 * false for scenery, where something that barely rises off the floor is taken as part of the floor. reach: how
		 * far from where it stands it is taken to reach at most, in the game's units.
		 */
		private void thing(Burst.Cut cut, Renderable renderable, int x, int y, int z, int orientation, boolean nearer, boolean lowToo, int reach)
		{
			if (renderable == null)
			{
				return;
			}
			z -= renderable.getAnimationHeightOffset();
			if (plain)
			{
				// Not worth working out the shape of something that is nowhere near the burst on screen
				double away = onScreen(x, y, z, spot);
				if (away < 0 || !cut.reaches(spot[0], spot[1], reach * scale / away + 4, nearer))
				{
					return;
				}
			}
			Model model = renderable instanceof Model ? (Model) renderable : renderable.getModel();
			if (model == null)
			{
				return;
			}
			int corners = model.getVerticesCount();
			float[] heightOf = model.getVerticesY();
			if (!lowToo)
			{
				// up is the smaller number
				float highest = 0;
				for (int i = 0; i < corners; i++)
				{
					highest = Math.min(highest, heightOf[i]);
				}
				if (-highest < FLOOR_THICK)
				{
					return;
				}
			}
			if (cornerX.length < corners)
			{
				cornerX = new int[corners];
				cornerY = new int[corners];
			}
			Perspective.modelToCanvas(client, world, corners, x, y, z, orientation, model.getVerticesX(), model.getVerticesZ(), heightOf, cornerX, cornerY);
			cut.faces(cornerX, cornerY, corners, model.getFaceIndices1(), model.getFaceIndices2(), model.getFaceIndices3(), model.getFaceTransparencies(),
				model.getFaceCount(), nearer);
		}
	}
}

package com.osrslootsim;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.hiscore.HiscoreSkill;

/**
 * Pictures from the game itself: item sprites by item ID, boss pictures from the hiscores' sprites.
 */
final class GameIcons implements Icons
{
	private static final int ITEMS_PER_FRAME = 2500;

	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;

	// Item IDs by lower-case name, for the items the simulator has no ID for (untradeables: pets, keys, clue scrolls).
	// Read from the game's own item list the first time one is needed, a slice per frame. Client thread only.
	private final Map<String, Integer> ids = new HashMap<>();
	private final List<Runnable> waiting = new ArrayList<>();
	private int scanned;
	private boolean scanning;
	private boolean indexed;

	GameIcons(Client client, ClientThread clientThread, ItemManager itemManager, SpriteManager spriteManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;
	}

	@Override
	public void item(JLabel label, int id, String name, long quantity)
	{
		int count = (int) Math.max(1, Math.min(quantity, Integer.MAX_VALUE));
		if (id > 0)
		{
			itemManager.getImage(id, count, count > 1).addTo(label);
			return;
		}
		byName(name, found -> SwingUtilities.invokeLater(() -> itemManager.getImage(found, count, count > 1).addTo(label)));
	}

	@Override
	public void picture(int id, String name, Consumer<BufferedImage> use)
	{
		if (id > 0)
		{
			use.accept(itemManager.getImage(id));
			return;
		}
		byName(name, found -> use.accept(itemManager.getImage(found)));
	}

	@Override
	public void boss(String name, Consumer<BufferedImage> use)
	{
		HiscoreSkill row = Hiscores.picture(name);
		if (row != null)
		{
			spriteManager.getSpriteAsync(row.getSpriteId(), 0, image -> SwingUtilities.invokeLater(() -> use.accept(image)));
		}
	}

	private void byName(String name, IntConsumer found)
	{
		String key = name.toLowerCase(Locale.ENGLISH);
		clientThread.invokeLater(() ->
		{
			Runnable look = () ->
			{
				Integer id = ids.get(key);
				if (id != null)
				{
					found.accept(id);
				}
			};
			if (indexed)
			{
				look.run();
				return;
			}
			waiting.add(look);
			if (!scanning)
			{
				scanning = true;
				clientThread.invokeLater((BooleanSupplier) this::scan);
			}
		});
	}

	/**
	 * Reads the next slice of the game's item list. Runs once a frame until it returns true.
	 */
	private boolean scan()
	{
		if (client.getGameState().getState() < GameState.LOGIN_SCREEN.getState())
		{
			return false;   // the game's files are still loading
		}
		int total = client.getItemCount();
		int end = Math.min(total, scanned + ITEMS_PER_FRAME);
		for (; scanned < end; scanned++)
		{
			ItemComposition item = client.getItemDefinition(scanned);
			// The bank note and placeholder of an item share its name: the item itself is the one to draw
			if (item == null || item.getNote() != -1 || item.getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			String name = item.getName();
			if (name != null && !name.isEmpty() && !name.equalsIgnoreCase("null"))
			{
				ids.putIfAbsent(name.toLowerCase(Locale.ENGLISH), scanned);
			}
		}
		if (scanned < total)
		{
			return false;
		}
		indexed = true;
		scanning = false;
		for (Runnable look : waiting)
		{
			look.run();
		}
		waiting.clear();
		return true;
	}
}

package com.osrslootsim;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

/**
 * Matches the simulator's names for bosses, raids and clues to their rows on the official hiscores.
 */
final class Hiscores
{
	// The simulator's names for sources the hiscores spell another way
	private static final Map<String, String> NAMES = new HashMap<>();

	// Sources the simulator counts in something other than the hiscores do (reward rolls, not games), so a hiscores
	// count would be the wrong number to simulate
	private static final Set<String> OTHER_UNITS = new HashSet<>(Arrays.asList("wintertodt", "tempoross", "guardians of the rift"));

	static
	{
		NAMES.put("barrows", "barrows chests");
		NAMES.put("the nightmare", "nightmare");
		NAMES.put("moons of peril", "lunar chests");
		NAMES.put("fortis colosseum", "sol heredit");
		NAMES.put("guardians of the rift", "rifts closed");
	}

	private Hiscores()
	{
	}

	/**
	 * The hiscores row whose picture stands for a source, or null. Every clue tier shares the one clue picture: the
	 * tiers' own rows have none.
	 */
	static HiscoreSkill picture(String source)
	{
		String name = source.toLowerCase(Locale.ENGLISH);
		HiscoreSkill row = find(name.startsWith("clue scroll (") ? "clue scrolls (all)" : NAMES.getOrDefault(name, name));
		return row != null && row.getSpriteId() > 0 ? row : null;
	}

	/**
	 * True for a source with a boss's row on the hiscores, raids among them: what the panel lets a player pin. Clues,
	 * minigames, chests and ordinary monsters have none.
	 */
	static boolean boss(String source)
	{
		HiscoreSkill row = picture(source);
		return row != null && row.getType() == HiscoreSkillType.BOSS;
	}

	/**
	 * The hiscores row that counts a source's kills, completions or caskets, or null when the hiscores have none that
	 * counts the same thing.
	 */
	static HiscoreSkill count(String source)
	{
		String name = source.toLowerCase(Locale.ENGLISH);
		if (otherUnit(source))
		{
			return null;
		}
		return find(name.startsWith("clue scroll (") ? name.replace("clue scroll (", "clue scrolls (") : NAMES.getOrDefault(name, name));
	}

	/**
	 * True for a source the simulator counts in reward rolls where the game counts games: no kill count fits it.
	 */
	static boolean otherUnit(String source)
	{
		return OTHER_UNITS.contains(source.toLowerCase(Locale.ENGLISH));
	}

	private static HiscoreSkill find(String name)
	{
		for (HiscoreSkill row : HiscoreSkill.values())
		{
			if (row.getName().toLowerCase(Locale.ENGLISH).equals(name))
			{
				return row;
			}
		}
		return null;
	}
}

package com.osrslootsim;

import java.time.LocalDate;

/**
 * Which holiday the Looting icon, the loot beam and the insane drop's sound are dressed for: whichever is in season,
 * none, or one of them all year.
 */
public enum HolidayLook
{
	BY_SEASON("By season"),
	OFF("Off"),
	HALLOWEEN("Halloween"),
	THANKSGIVING("Thanksgiving"),
	CHRISTMAS("Christmas");

	private final String name;

	HolidayLook(String name)
	{
		this.name = name;
	}

	Season season(LocalDate today)
	{
		switch (this)
		{
			case OFF:
				return Season.NONE;
			case HALLOWEEN:
				return Season.HALLOWEEN;
			case THANKSGIVING:
				return Season.THANKSGIVING;
			case CHRISTMAS:
				return Season.CHRISTMAS;
			default:
				return Season.on(today);
		}
	}

	@Override
	public String toString()
	{
		return name;
	}
}

