	// The picked boss's button, when the boss is pinned, has an orange edge
	private void markPicked()
	{
		String selected = picker.selected();
		for (Map.Entry<String, JButton> pin : pinButtons.entrySet())
		{
			boolean on = pin.getKey().equals(selected);
			pin.getValue().setBorder(BorderFactory.createLineBorder(on ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR));
		}
	}

	/**
	 * The pinned bosses as the settings hold them: MOST_PINS at most, each once, and bosses only.
	 */
	private List<String> savedPins()
	{
		List<String> names = new ArrayList<>();
		for (String saved : String.valueOf(config.pinnedBosses()).split(","))
		{
			String name = Text.plain(saved, 60);
			if (names.size() < BossPicker.MOST_PINS && !names.contains(name) && Hiscores.boss(name))
			{
				names.add(name);
			}
		}
		return names;
	}

	/**
	 * A boss's pin was pressed: pins the boss, or unpins it when it was pinned. One more than MOST_PINS is not pinned.
	 */
	private void pin(String boss)
	{
		if (!pins.remove(boss))
		{
			if (pins.size() >= BossPicker.MOST_PINS || !Hiscores.boss(boss))
			{
				return;
			}
			pins.add(boss);
		}
		config.pinnedBosses(String.join(",", pins));
		showPins();
	}

	/**
	 * Fills the row under the boss box: a button with each pinned boss's picture, which picks that boss. Right-click
	 * one to unpin it. With nothing pinned the row is hidden.
	 */
	private void showPins()
	{
		pinRow.removeAll();
		pinButtons.clear();
		for (String name : pins)
		{
			JButton button = new JButton();
			button.setToolTipText(name);
			button.getAccessibleContext().setAccessibleName(name);
			button.setPreferredSize(new Dimension(0, 30));
			button.setFocusPainted(false);
			button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			button.addActionListener(e -> picker.select(name));
			icons.boss(name, image -> button.setIcon(new ImageIcon(image)));
			JMenuItem unpin = new JMenuItem("Unpin");
			unpin.addActionListener(e -> pin(name));
			JPopupMenu menu = new JPopupMenu();
			menu.add(unpin);
			button.setComponentPopupMenu(menu);
			pinButtons.put(name, button);
			pinRow.add(button);
		}
		for (int empty = pins.size(); empty < BossPicker.MOST_PINS; empty++)
		{
			pinRow.add(clear(new JPanel()));   // so a button is a fifth of the row wide however many there are
		}
		pinRow.setVisible(!pins.isEmpty());
		picker.showPins(pins);
		markPicked();
		revalidate();
		repaint();
	}

	/**
	 * Shows the picked boss's options row, asking the site for it the first time the boss is picked.
	 */
	private void loadOptions()
	{
		String boss = picker.selected();
		if (!opened || boss == null)
		{
			return;
		}
		List<LootSimApi.Option> known = optionLists.get(boss);
		optionsBar.offer(boss, known);   // nothing yet hides the row until the answer is in
		revalidate();
		if (known != null)
		{
			return;
		}
		api.options(boss, list ->
		{
			optionLists.put(boss, list.options);
			if (boss.equals(picker.selected()))
			{
				optionsBar.offer(boss, list.options);
				revalidate();
			}
		}, error ->
		{
			// no row for this boss: it is simulated with the site's usual settings
		});
	}

	/**
	 * Asks the site for the boss box's lists the first time the panel is opened. Until they arrive, and if they never
	 * do, the box holds five well-known ones.
	 */
	private void loadBosses()
	{
		if (bossesLoaded || bossesLoading)
		{
			return;
		}
		bossesLoading = true;
		api.bosses(list ->
		{
			bossesLoading = false;
			bossesLoaded = true;
			if (list.maxKills > 0)
			{
				maxKills = Math.min(list.maxKills, 99999);
			}
			Set<String> names = new LinkedHashSet<>();
			for (LootSimApi.Boss boss : list.bosses)
			{
				String name = Text.plain(boss.name, 60);
				if (!name.isEmpty())
				{
					names.add(name);
				}
			}
			names.addAll(USUAL);
			List<String> all = new ArrayList<>();
			if (list.all != null)
			{
				for (String name : list.all)
				{
					String clean = Text.plain(name, 60);
					if (!clean.isEmpty())
					{
						all.add(clean);
					}
				}
			}
			Set<String> known = new LinkedHashSet<>(names);
			known.addAll(all);
			Map<String, String> aliases = new HashMap<>();
			if (list.aliases != null)
			{
				for (Map.Entry<String, String> alias : list.aliases.entrySet())
				{
					String name = Text.plain(alias.getValue(), 60);
					if (alias.getKey() != null && known.contains(name))
					{
						aliases.put(Text.plain(alias.getKey(), 40), name);
					}
				}
			}
			picker.setBosses(new ArrayList<>(names), all, aliases);
		}, error -> bossesLoading = false);
	}

	/**
	 * A line under the Simulate button, wrapped to the panel's width; an empty text hides it.
	 */
	private void say(String text)
	{
		statusText = text;
		status.removeAll();
		for (String line : wrap(text, getFontMetrics(SMALL), TEXT_WIDTH))
		{
			status.add(label(line, ColorScheme.LIGHT_GRAY_COLOR));
		}
		status.setVisible(!text.isEmpty());
		revalidate();
		repaint();
	}

	private static List<String> wrap(String text, FontMetrics metrics, int width)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.trim().split("\\s+"))
		{
			if (line.length() > 0 && metrics.stringWidth(line + " " + word) > width)
			{
				lines.add(line.toString());
				line.setLength(0);
			}
			line.append(line.length() > 0 ? " " : "").append(word);
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

