@PluginDescriptor(
	name = "OSRS Loot Sim",
	description = "Simulate kills at any boss, raid or clue from the side panel: the loot, its value and your chance of each rare drop by now. Uses osrslootsim.com",
	// Kept the same as the tags in runelite-plugin.properties, which the Plugin Hub searches. A typed word finds the
	// plugin when it is part of one of these, or of a word in the name or the description.
	tags = {"loot", "drop", "drops", "drop rate", "drop table", "simulator", "simulation", "calculator", "calc", "odds", "probability", "rng", "luck",
		"lucky", "dry", "dry streak", "dryness", "kc", "kill count", "killcount", "bosses", "bossing", "pvm", "raids", "cox", "tob", "toa", "clues",
		"casket", "chest", "pet", "pets", "unique", "uniques", "purple", "collection log", "clog", "loot beam"}
)
public class LootSimPlugin extends Plugin implements Account
{
	static final String CONFIG_GROUP = "osrslootsim";
	private static final String XP_KEY = "xp";

	// Where RuneLite's own Chat Commands plugin keeps the kill counts it reads from chat, under the boss's name in
	// lower case. A few sources go by another name there than in the simulator.
	private static final String KILLCOUNT_GROUP = "killcount";
	// How the game announces a new collection log item: a line in chat, a pop-up at the top of the screen, or both
	private static final String COLLECTION_LOG_CHAT = "New item added to your collection log:";
	private static final String COLLECTION_LOG_POPUP = "Collection log";
	private static final String COLLECTION_LOG_POPUP_LEAD = "New item:";
	private static final Map<String, String> KILLCOUNT_NAMES = new HashMap<>();

	static
	{
		KILLCOUNT_NAMES.put("barrows", "barrows chests");
		KILLCOUNT_NAMES.put("moons of peril", "lunar chest");
		KILLCOUNT_NAMES.put("fortis colosseum", "sol heredit");
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private LootSimConfig config;

	@Inject
	private HiscoreClient hiscoreClient;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private AudioPlayer audioPlayer;

	@Inject
	private EventBus eventBus;

	@Inject
	private RuneLiteConfig runeLiteConfig;

	private LootSimPanel panel;
	private NavigationButton navButton;
	private DropPopups popups;

	// The account's levels as last seen, to tell a level gained from the game simply reporting its stats (as it
	// does for every skill at login)
	private final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
	// The game's pop-up at the top of the screen is announced in two steps: the second reads what the first set up
	private boolean notificationStarted;
	// Never shown. RuneLite opens a plugin's settings when "Configure" is picked on one of the plugin's overlays, and
	// gives plugins no other way to ask for that: this is the overlay it is told about.
	private final Overlay settingsHandle = new Overlay(this)
	{
		@Override
		public Dimension render(Graphics2D graphics)
		{
			return null;
		}
	};

	@Provides
	LootSimConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LootSimConfig.class);
	}

	@Override
	protected void startUp()
	{
		GameIcons icons = new GameIcons(client, clientThread, itemManager, spriteManager);
		popups = new DropPopups(client, clientThread, config, icons, overlayManager, audioPlayer, runeLiteConfig);
		popups.start();
		panel = new LootSimPanel(new LootSimApi(okHttpClient, gson), icons, this, config);
		panel.onRun(popups::ran);
		panel.onSettings(() -> eventBus.post(new OverlayMenuClicked(
			new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OverlayManager.OPTION_CONFIGURE, getName()), settingsHandle)));
		panel.onLevelUp(() ->
		{
			if (config.levelUpBeam())
			{
				popups.burst();
			}
		});
		BufferedImage icon = ImageUtil.loadImageResource(LootSimPlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("OSRS Loot Sim")
			.icon(ImageUtil.resizeImage(icon, 16, 16))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		popups.stop();
		popups = null;
		levels.clear();
		navButton = null;
		panel = null;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.settingsChanged();
			}
		});
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Integer before = levels.put(event.getSkill(), event.getLevel());
		if (before != null && event.getLevel() > before && config.levelUpBeam() && popups != null)
		{
			popups.burst();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Another login may be another account: its levels are not gains over the last one's
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			levels.clear();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE || popups == null)
		{
			return;
		}
		String line = net.runelite.client.util.Text.removeTags(event.getMessage());
		if (line.startsWith(COLLECTION_LOG_CHAT))
		{
			popups.collected(line.substring(COLLECTION_LOG_CHAT.length()).trim());
		}
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		looted(event.getItems());
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		looted(event.getItems());
	}

	// Chests, raids, clues and the rest, as RuneLite's own Loot Tracker plugin reports them while it is switched on.
	// It reports kills too: two reports of one kill are one burst.
	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		looted(event.getItems());
	}

	/**
	 * Loot arrived in the game: shows the loot beam when that is switched on and the loot is worth enough, all of it
	 * together at Grand Exchange prices.
	 */
	private void looted(Collection<ItemStack> items)
	{
		if (!config.lootBeam() || popups == null || items == null || items.isEmpty())
		{
			return;
		}
		long worth = 0;
		for (ItemStack item : items)
		{
			worth += (long) itemManager.getItemPrice(item.getId()) * item.getQuantity();
		}
		if (worth >= Math.max(0, Math.min(LootSimConfig.MOST_LOOT_VALUE, config.lootBeamValue())))
		{
			popups.burst();
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		// The collection log's pop-up, for players who have its chat line switched off. Read the way RuneLite's own
		// Screenshot plugin reads it.
		if (event.getScriptId() == ScriptID.NOTIFICATION_START)
		{
			notificationStarted = true;
		}
		else if (event.getScriptId() == ScriptID.NOTIFICATION_DELAY && notificationStarted)
		{
			notificationStarted = false;
			String title = client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
			if (COLLECTION_LOG_POPUP.equalsIgnoreCase(title) && popups != null)
			{
				// "New item:" and the item's name, on two lines
				String text = net.runelite.client.util.Text.removeTags(String.valueOf(client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN))).trim();
				popups.collected(text.startsWith(COLLECTION_LOG_POPUP_LEAD) ? text.substring(COLLECTION_LOG_POPUP_LEAD.length()).trim() : text);
			}
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.accountChanged();
			}
		});
	}

	@Override
	public boolean known()
	{
		return configManager.getRSProfileKey() != null;
	}

	@Override
	public long xp()
	{
		if (!known())
		{
			return 0;
		}
		Integer xp = configManager.getRSProfileConfiguration(CONFIG_GROUP, XP_KEY, Integer.class);
		return xp == null ? 0 : Math.max(0, Math.min(xp, Looting.MAX_XP));
	}

	@Override
	public void addXp(long gained)
	{
		if (known() && gained > 0)
		{
			// 200,000,000 at most, so it fits a whole number setting
			configManager.setRSProfileConfiguration(CONFIG_GROUP, XP_KEY, (int) Math.min(Looting.MAX_XP, xp() + gained));
		}
	}

	@Override
	public void killCount(String boss, Consumer<Integer> answer)
	{
		Integer saved = savedKillCount(boss);
		HiscoreSkill row = Hiscores.count(boss);
		if (row == null)
		{
			answer.accept(saved);
			return;
		}
		// The official hiscores, asked the way RuneLite's own Hiscore panel asks them: by the character's name
		clientThread.invoke(() ->
		{
			Player player = client.getLocalPlayer();
			String name = player == null ? null : player.getName();
			if (name == null)
			{
				SwingUtilities.invokeLater(() -> answer.accept(saved));
				return;
			}
			hiscoreClient.lookupAsync(name, HiscoreEndpoint.fromWorldTypes(client.getWorldType())).whenComplete((result, error) ->
			{
				net.runelite.client.hiscore.Skill listed = result == null ? null : result.getSkill(row);
				int count = Math.max(saved == null ? 0 : saved, listed == null ? 0 : listed.getLevel());
				SwingUtilities.invokeLater(() -> answer.accept(count > 0 ? count : null));
			});
		});
	}

	/**
	 * The kill count RuneLite last read from chat for a boss, or null.
	 */
	private Integer savedKillCount(String boss)
	{
		if (!known() || Hiscores.otherUnit(boss))
		{
			return null;
		}
		String name = boss.toLowerCase(Locale.ENGLISH);
		String[] keys = {KILLCOUNT_NAMES.getOrDefault(name, name), name.startsWith("the ") ? name.substring(4) : name};
		for (String key : keys)
		{
			Integer count = configManager.getRSProfileConfiguration(KILLCOUNT_GROUP, key, Integer.class);
			if (count != null && count > 0)
			{
				return count;
			}
		}
		return null;
	}
}

package com.osrslootsim;

import net.runelite.api.Experience;

/**
 * The plugin's Looting level: 1 to 99 on the game's own experience curve, like the level on osrslootsim.com. The two
 * are separate: the site keeps its level in the visitor's browser, the plugin keeps this one per RuneScape account.
 */
final class Looting
{
	static final long MAX_XP = Experience.MAX_SKILL_XP;

	private Looting()
	{
	}

	static int level(long xp)
	{
		int capped = (int) Math.max(0, Math.min(xp, MAX_XP));
		return Math.min(Experience.MAX_REAL_LEVEL, Experience.getLevelForXp(capped));
	}

	/**
	 * How far through the current level the xp is, from 0 to 1. Always 1 at level 99.
	 */
	static double progress(long xp)
	{
		int level = level(xp);
		if (level >= Experience.MAX_REAL_LEVEL)
		{
			return 1;
		}
		long from = Experience.getXpForLevel(level);
		long to = Experience.getXpForLevel(level + 1);
		return Math.max(0, Math.min(1, (double) (xp - from) / (to - from)));
	}

	/**
	 * The xp still needed for the next level, or 0 at level 99.
	 */
	static long toNext(long xp)
	{
		int level = level(xp);
		return level >= Experience.MAX_REAL_LEVEL ? 0 : Experience.getXpForLevel(level + 1) - xp;
	}
}

package com.osrslootsim;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.text.AbstractDocument;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The row of settings above the kills box: what the picked boss can be simulated with. Challenge Mode and a team
 * size at a raid, skulled at revenants, on a slayer task where that changes the drops. The site says which a boss has
 * (one row's worth at most), so the row is empty and hidden for a boss with none. A switch is a small button, lit
 * while it is on; a number is a short box.
 */
final class OptionsBar extends JPanel
{
	private static final String TOGGLE = "toggle";
	private static final String NUMBER = "number";
	private static final int MAX_OPTIONS = 6;
	private static final int ROW_HEIGHT = 24;
	private static final int GAP = 4;
	private static final Font SMALL = FontManager.getRunescapeSmallFont();

	// What the player set for each boss, so coming back to a boss finds it as they left it
	private final Map<String, Map<String, Integer>> remembered = new HashMap<>();
	private List<LootSimApi.Option> options = Collections.emptyList();
	private Map<String, Integer> values = new HashMap<>();
	private String boss = "";

	OptionsBar()
	{
		super(new GridBagLayout());
		setOpaque(false);
		setVisible(false);
	}

	/**
	 * Shows a boss's settings; none hides the row.
	 */
	void offer(String boss, List<LootSimApi.Option> offered)
	{
		this.boss = boss;
		options = usable(offered);
		values = remembered.computeIfAbsent(boss, b -> new HashMap<>());
		removeAll();
		GridBagConstraints at = new GridBagConstraints();
		at.gridy = 0;
		at.insets = new Insets(0, 0, 0, GAP);
		for (LootSimApi.Option option : options)
		{
			if (TOGGLE.equals(option.kind))
			{
				add(toggle(option), at);
			}
			else
			{
				JTextField box = box(option);
				JLabel name = new JLabel(option.label);
				name.putClientProperty("html.disable", Boolean.TRUE);
				name.setFont(SMALL);
				name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				name.setToolTipText(option.tip);
				name.setLabelFor(box);
				add(name, at);
				add(box, at);
			}
		}
		at.weightx = 1;   // what is left of the row stays empty, so the settings sit at its left
		add(new JLabel(), at);
		setVisible(!options.isEmpty());
		revalidate();
		repaint();
	}

	/**
	 * The settings as the simulator takes them, "cm:1,team:3", or nothing for a boss without any.
	 */
	String settings()
	{
		StringBuilder out = new StringBuilder();
		for (LootSimApi.Option option : options)
		{
			out.append(out.length() > 0 ? "," : "").append(option.id).append(':').append(value(option));
		}
		return out.toString();
	}

	/**
	 * Sets one of the shown settings. For the panel preview.
	 */
	void choose(String id, int value)
	{
		values.put(id, value);
		offer(boss, options);
	}

	private int value(LootSimApi.Option option)
	{
		Integer set = values.get(option.id);
		if (TOGGLE.equals(option.kind))
		{
			return set == null ? (option.on ? 1 : 0) : (set != 0 ? 1 : 0);
		}
		int step = Math.max(1, option.step);
		int number = set == null ? option.value : set;
		number = Math.round((float) number / step) * step;
		return Math.max(option.min, Math.min(option.max, number));
	}

	private JButton toggle(LootSimApi.Option option)
	{
		JButton button = new JButton(option.label);
		button.putClientProperty("html.disable", Boolean.TRUE);
		button.setFont(SMALL);
		button.setFocusPainted(false);
		button.setMargin(new Insets(2, 2, 2, 2));
		button.setToolTipText(option.tip);
		// Sized by its word: the look and feel's own least width would make five of them overflow the row
		button.setPreferredSize(new Dimension(getFontMetrics(SMALL).stringWidth(option.label) + 14, ROW_HEIGHT));
		light(button, value(option) == 1);
		button.addActionListener(e ->
		{
			values.put(option.id, value(option) == 1 ? 0 : 1);
			light(button, value(option) == 1);
		});
		return button;
	}

	private static void light(JButton button, boolean on)
	{
		button.setBackground(on ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR);
		button.setForeground(on ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
		button.getAccessibleContext().setAccessibleDescription(on ? "on" : "off");
	}

	private JTextField box(LootSimApi.Option option)
	{
		int digits = String.valueOf(option.max).length();
		JTextField box = new JTextField(String.valueOf(value(option)));
		box.setFont(SMALL);
		box.setForeground(Color.WHITE);
		box.setHorizontalAlignment(SwingConstants.CENTER);
		box.setToolTipText(option.tip + " (" + Text.number(option.min) + " to " + Text.number(option.max) + ")");
		box.setPreferredSize(new Dimension(digits * 7 + 14, ROW_HEIGHT));
		((AbstractDocument) box.getDocument()).setDocumentFilter(new DigitsOnly(digits));
		// Typing is taken as it comes; leaving the box, or Enter, pulls the number into its range
		Runnable settle = () ->
		{
			try
			{
				values.put(option.id, Integer.parseInt(box.getText().trim()));
			}
			catch (NumberFormatException e)
			{
				values.remove(option.id);
			}
			box.setText(String.valueOf(value(option)));
		};
		box.addActionListener(e -> settle.run());
		box.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				settle.run();
			}
		});
		box.getDocument().addDocumentListener(new javax.swing.event.DocumentListener()
		{
			@Override
			public void insertUpdate(javax.swing.event.DocumentEvent e)
			{
				typed();
			}

			@Override
			public void removeUpdate(javax.swing.event.DocumentEvent e)
			{
				typed();
			}

			@Override
			public void changedUpdate(javax.swing.event.DocumentEvent e)
			{
			}

			private void typed()
			{
				try
				{
					values.put(option.id, Integer.parseInt(box.getText().trim()));
				}
				catch (NumberFormatException e)
				{
					values.remove(option.id);
				}
			}
		});
		return box;
	}

	/**
	 * The options of the site's list that this version can show, with their words made safe to draw.
	 */
	private static List<LootSimApi.Option> usable(List<LootSimApi.Option> offered)
	{
		List<LootSimApi.Option> out = new ArrayList<>();
		if (offered == null)
		{
			return out;
		}
		for (LootSimApi.Option option : offered)
		{
			if (option == null || option.id == null || !option.id.matches("[a-z0-9-]{1,20}") || out.size() >= MAX_OPTIONS)
			{
				continue;
			}
			option.label = Text.plain(option.label, 10);
			option.tip = Text.plain(option.tip, 120);
			boolean number = NUMBER.equals(option.kind) && option.min >= 0 && option.max >= option.min && option.max <= 9_999_999;
			if (option.label.isEmpty() || !(TOGGLE.equals(option.kind) || number))
			{
				continue;
			}
			out.add(option);
		}
		return out;
	}
}

package com.osrslootsim;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import javax.swing.Icon;

/**
 * A small drawing pin, for pinning a boss to the row under the boss box: solid on a boss that is pinned, an outline
 * on one that is not.
 */
final class Pin implements Icon
{
	private static final int SIZE = 14;
	private static final double LEAN = Math.toRadians(40);
	private static final Shape HEAD = head();

	private final Color colour;
	private final boolean solid;

	Pin(Color colour, boolean solid)
	{
		this.colour = colour;
		this.solid = solid;
	}

	@Override
	public void paintIcon(Component c, Graphics g, int x, int y)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g2.translate(x + SIZE / 2.0, y + SIZE / 2.0);
		g2.rotate(LEAN);
		g2.setColor(colour);
		g2.setStroke(new BasicStroke(1.1f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		if (solid)
		{
			g2.fill(HEAD);
		}
		g2.draw(HEAD);
		g2.draw(new Line2D.Double(0, 1.6, 0, 6.2));   // the needle
		g2.dispose();
	}

	@Override
	public int getIconWidth()
	{
		return SIZE;
	}

	@Override
	public int getIconHeight()
	{
		return SIZE;
	}

	// The cap, the grip that widens under it and the plate the needle comes out of, standing upright around 0, 0
	private static Shape head()
	{
		Path2D head = new Path2D.Double();
		head.moveTo(-3, -6);
		head.lineTo(3, -6);
		head.lineTo(3, -4.8);
		head.lineTo(2, -4.8);
		head.lineTo(2, -1.6);
		head.quadTo(2.4, 0, 4, 0.4);
		head.lineTo(4, 1.6);
		head.lineTo(-4, 1.6);
		head.lineTo(-4, 0.4);
		head.quadTo(-2.4, 0, -2, -1.6);
		head.lineTo(-2, -4.8);
		head.lineTo(-3, -4.8);
		head.closePath();
		return head;
	}
}

package com.osrslootsim;

import java.time.LocalDate;

/**
 * The holiday the Looting icon dresses for, by the player's own date, on the same calendar as osrslootsim.com:
 * Halloween from 1 October to 2 November, Thanksgiving from 3 November to the day after US Thanksgiving, Christmas
 * from 1 December to New Year's Day. A few plain days lie between Thanksgiving and Christmas.
 */
enum Season
{
	NONE(""),
	HALLOWEEN("-halloween"),
	THANKSGIVING("-thanksgiving"),
	CHRISTMAS("-christmas");

	private final String suffix;

	Season(String suffix)
	{
		this.suffix = suffix;
	}

	/**
	 * The still Looting icon for this season, 16 by 16, next to the plugin's classes.
	 */
	String still()
	{
		return "looting" + suffix + ".png";
	}

	/**
	 * The moving Looting icon for this season: its frames side by side in one picture.
	 */
	String strip()
	{
		return "looting-anim" + suffix + ".png";
	}

	/**
	 * The site's pet fanfare for this season, as a sound file next to the plugin's classes.
	 */
	String fanfare()
	{
		return "pet" + suffix + ".wav";
	}

	static Season on(LocalDate day)
	{
		int date = day.getMonthValue() * 100 + day.getDayOfMonth();
		if (date >= 1001 && date <= 1102)
		{
			return HALLOWEEN;
		}
		if (date >= 1103 && date <= 1100 + thanksgiving(day.getYear()) + 1)
		{
			return THANKSGIVING;
		}
		if (date >= 1201 || date == 101)
		{
			return CHRISTMAS;
		}
		return NONE;
	}

	/**
	 * The day of November that US Thanksgiving falls on: its fourth Thursday.
	 */
	static int thanksgiving(int year)
	{
		int firstDay = LocalDate.of(year, 11, 1).getDayOfWeek().getValue() % 7;   // Sunday 0 to Saturday 6
		return 22 + (11 - firstDay) % 7;
	}
}

package com.osrslootsim;

import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;
import javax.swing.Timer;
import net.runelite.client.util.ImageUtil;

/**
 * The Looting skill icon beside the level, as on osrslootsim.com: a loot beam over a stack of coins that fires every
 * three seconds, dressed for the holiday in season, at the icon's own 16-pixel size (a holiday's has a little room
 * around it for what flies out). It moves only while the panel is open. With the movement switched off it is the
 * still icon.
 */
final class SkillIcon extends JComponent
{
	// Every strip holds the same three-second loop: this many frames side by side, at this many a second
	private static final int FRAMES = 45;
	private static final int FRAMES_PER_SECOND = 15;

	private final Timer timer = new Timer(1000 / FRAMES_PER_SECOND, e -> step());
	private BufferedImage strip;
	private BufferedImage still;
	private Season season;
	private boolean moving;
	private boolean playing;
	private int frame;

	SkillIcon()
	{
		set(Season.NONE, false);
	}

	/**
	 * Which icon to show, and whether it moves.
	 */
	void set(Season season, boolean moving)
	{
		if (season == this.season && moving == this.moving)
		{
			return;
		}
		this.season = season;
		this.moving = moving;
		still = ImageUtil.loadImageResource(SkillIcon.class, season.still());
		strip = moving ? ImageUtil.loadImageResource(SkillIcon.class, season.strip()) : null;
		frame = 0;
		setPreferredSize(strip != null ? new Dimension(strip.getWidth() / FRAMES, strip.getHeight())
			: new Dimension(still.getWidth(), still.getHeight()));
		run();
		revalidate();
		repaint();
	}

	/**
	 * The panel opening (true) or closing (false): the icon only moves while someone can see it.
	 */
	void play(boolean playing)
	{
		this.playing = playing;
		run();
	}

	/**
	 * Shows one frame of the loop and holds it. For the panel preview.
	 */
	void hold(int frame)
	{
		timer.stop();
		this.frame = Math.floorMod(frame, FRAMES);
		repaint();
	}

	private void run()
	{
		if (strip != null && playing)
		{
			timer.start();
		}
		else
		{
			timer.stop();
		}
	}

	private void step()
	{
		frame = (frame + 1) % FRAMES;
		if (isShowing())
		{
			repaint();
		}
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		if (strip == null)
		{
			g.drawImage(still, (getWidth() - still.getWidth()) / 2, getHeight() - still.getHeight(), null);
			return;
		}
		int width = strip.getWidth() / FRAMES;
		int x = (getWidth() - width) / 2;
		int y = getHeight() - strip.getHeight();
		g.drawImage(strip, x, y, x + width, y + strip.getHeight(), frame * width, 0, (frame + 1) * width, strip.getHeight(), null);
	}
}

package com.osrslootsim;

import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/**
 * Wording and number formats the panel shares.
 */
final class Text
{
	private static final DecimalFormatSymbols ENGLISH = DecimalFormatSymbols.getInstance(Locale.ENGLISH);

	private Text()
	{
	}

	/**
	 * Text from the simulator, made safe to show: Swing draws a label or tooltip that starts with an HTML tag as
	 * HTML, so angle brackets and control characters are dropped and the length is capped.
	 */
	static String plain(String text, int max)
	{
		if (text == null)
		{
			return "";
		}
		StringBuilder out = new StringBuilder();
		for (int i = 0; i < text.length() && out.length() < max; i++)
		{
			char c = text.charAt(i);
			if (c != '<' && c != '>' && c >= ' ' && c != 127)
			{
				out.append(c);
			}
		}
		return out.toString().trim();
	}

	/**
	 * 1234567 as "1,234,567".
	 */
	static String number(long n)
	{
		return new DecimalFormat("#,##0", ENGLISH).format(n);
	}

	/**
	 * A coin total short enough for a narrow header: "14,269 gp", "681K gp", "15.14M gp", "2.56B gp".
	 */
	static String coins(long gp)
	{
		if (gp < 100_000)
		{
			return number(gp) + " gp";
		}
		if (gp < 10_000_000)
		{
			return number(gp / 1000) + "K gp";
		}
		DecimalFormat two = new DecimalFormat("#,##0.00", ENGLISH);
		return gp < 1_000_000_000 ? two.format(gp / 1e6) + "M gp" : two.format(gp / 1e9) + "B gp";
	}

	/**
	 * A drop rate as the site writes it: "1/5,000", "1/64", "1/12.5", "1/2.25".
	 */
	static String rate(double oneIn)
	{
		if (!(oneIn >= 1))
		{
			return "1/1";
		}
		if (oneIn >= 100)
		{
			return "1/" + number(Math.round(oneIn));
		}
		String digits = new DecimalFormat(oneIn < 10 ? "0.##" : "0.#", ENGLISH).format(oneIn);
		return "1/" + digits;
	}

	/**
	 * A chance from 0 to 1 as a percentage that never rounds to a flat 0% or 100% unless it is one.
	 */
	static String percent(double chance)
	{
		double pct = 100 * Math.max(0, Math.min(1, chance));
		if (pct > 0 && pct < 0.1)
		{
			return "<0.1%";
		}
		if (pct > 99.9 && pct < 100)
		{
			return ">99.9%";
		}
		return new DecimalFormat("0.0", ENGLISH).format(pct) + "%";
	}

	/**
	 * "kill" as "kills", "search" as "searches": what one run of a source is counted in, for more than one.
	 */
	static String plural(String unit)
	{
		String word = plain(unit, 20).toLowerCase(Locale.ENGLISH);
		if (word.isEmpty())
		{
			word = "kill";
		}
		return word.matches(".*(ch|sh|s|x)$") ? word + "es" : word + "s";
	}
}

package com.osrslootsim;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Random;
import java.util.function.Consumer;
import javax.swing.JLabel;

/**
 * Times the parts of the plugin that run every frame or every keystroke, without the game: the loot beam at two
 * screen sizes for the regular look and each holiday, the chat card, and a search of the boss box. Run it with
 * "gradlew bench". The game draws 50 frames a second, 20 ms each, and a plugin should take a small part of that.
 */
public final class Bench
{
	private static final int WARM_UP = 150;
	private static final int FRAMES = 300;
	private static final int SHOWN_MS = 4800;

	public static void main(String[] args)
	{
		System.out.println("loot beam, milliseconds a frame over its 4.8 s (median / 95th percentile / worst), with a 3,000-face character and 6,000 faces of scenery cut out");
		// the game at its fixed size, the camera at an ordinary distance; and a big window zoomed right in
		time("fixed 512x334, tile 44 px ", new Rectangle(4, 4, 512, 334), 44, 260, 210, 40, 90);
		time("large 1640x1000, tile 120 px", new Rectangle(0, 0, 1640, 1000), 120, 820, 640, 110, 250);

		BufferedImage canvas = new BufferedImage(600, 300, BufferedImage.TYPE_INT_ARGB_PRE);
		Graphics2D g = canvas.createGraphics();
		DropCard.Drop drop = new DropCard.Drop(DropCard.Kind.INSANE, "Tumeken's shadow (uncharged)");
		drop.picture = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		long[] card = new long[FRAMES];
		for (int i = -WARM_UP; i < FRAMES; i++)
		{
			long began = System.nanoTime();
			DropCard.paintCard(g, 20, 20, 1f, drop, 0.9f);
			if (i >= 0)
			{
				card[i] = System.nanoTime() - began;
			}
		}
		g.dispose();
		System.out.println("chat card: " + report(card));

		// the boss box: every keystroke filters the full list
		List<String> names = new ArrayList<>();
		Random random = new Random(7);
		for (int i = 0; i < 1708; i++)
		{
			StringBuilder name = new StringBuilder();
			for (int j = 0; j < 6 + random.nextInt(14); j++)
			{
				name.append((char) (j > 0 && random.nextInt(7) == 0 ? ' ' : 'a' + random.nextInt(26)));
			}
			names.add(name.toString());
		}
		Icons none = new Icons()
		{
			@Override
			public void item(JLabel label, int id, String name, long quantity)
			{
			}

			@Override
			public void picture(int id, String name, Consumer<BufferedImage> use)
			{
			}

			@Override
			public void boss(String name, Consumer<BufferedImage> use)
			{
			}
		};
		BossPicker picker = new BossPicker(none, names.subList(0, 177), names.get(0));
		picker.setBosses(names.subList(0, 177), names, Collections.emptyMap());
		String[] typed = {"a", "ab", "abc", "e", "th", "s", "zzzz", "o", "an"};
		long[] search = new long[FRAMES];
		for (int i = -WARM_UP; i < FRAMES; i++)
		{
			long began = System.nanoTime();
			picker.type(typed[Math.floorMod(i, typed.length)]);
			if (i >= 0)
			{
				search[i] = System.nanoTime() - began;
			}
		}
		System.out.println("boss search, one keystroke over 1,708 names: " + report(search));
	}

	private static void time(String label, Rectangle view, int tileWide, int footX, int footY, int bodyWide, int bodyTall)
	{
		BufferedImage canvas = new BufferedImage(view.x + view.width, view.y + view.height, BufferedImage.TYPE_INT_ARGB_PRE);
		Stage stage = new Stage(footX, footY, tileWide, 27, 0, 12);
		// A stand-in for the character's model: small faces scattered over the space a character fills. And for the
		// scenery around it: twice as many, scattered over the floor the burst covers and a little above it.
		Random random = new Random(3);
		int[][] body = faces(random, 3000, footX - bodyWide / 2, footY - bodyTall, bodyWide, bodyTall);
		int[][] scenery = faces(random, 6000, footX - 3 * tileWide, footY - 2 * tileWide, 6 * tileWide, 3 * tileWide);
		Consumer<Burst.Cut> infront = cut ->
		{
			cut.faces(body[0], body[1], body[0].length, body[2], body[3], body[4], null, body[2].length, true);
			cut.faces(scenery[0], scenery[1], scenery[0].length, scenery[2], scenery[3], scenery[4], null, scenery[2].length, false);
		};
		for (Season season : Season.values())
		{
			Burst.Glow glow = BeamColour.BY_HOLIDAY.glow(season);
			long[] took = new long[FRAMES];
			Graphics2D g = canvas.createGraphics();
			for (int i = -WARM_UP; i < FRAMES; i++)
			{
				long age = (long) Math.floorMod(i, FRAMES) * SHOWN_MS / FRAMES;
				long began = System.nanoTime();
				Burst.paint(g, view, stage, age, 1f, season, glow, infront);
				if (i >= 0)
				{
					took[i] = System.nanoTime() - began;
				}
			}
			g.dispose();
			System.out.println("  " + label + "  " + String.format("%-12s", season) + report(took));
		}
		Burst.release();
	}

	// So many small triangles scattered over a box on screen: the corners' x and y, then each face's three corners
	private static int[][] faces(Random random, int count, int left, int top, int wide, int tall)
	{
		int[][] model = {new int[3 * count], new int[3 * count], new int[count], new int[count], new int[count]};
		for (int face = 0; face < count; face++)
		{
			int x = left + random.nextInt(wide);
			int y = top + random.nextInt(tall);
			for (int corner = 0; corner < 3; corner++)
			{
				model[0][3 * face + corner] = x + random.nextInt(9) - 4;
				model[1][3 * face + corner] = y + random.nextInt(9) - 4;
				model[2 + corner][face] = 3 * face + corner;
			}
		}
		return model;
	}

	private static String report(long[] nanos)
	{
		long[] sorted = nanos.clone();
		Arrays.sort(sorted);
		return String.format("%.2f / %.2f / %.2f ms", sorted[sorted.length / 2] / 1e6, sorted[sorted.length * 95 / 100] / 1e6, sorted[sorted.length - 1] / 1e6);
	}
}

package com.osrslootsim;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;

/**
 * Draws the pop-up card and the burst to a PNG without starting the game. On the left the card four ways: for an
 * insane drop, for a collection log item, unlocked at one and a half times its size, and at its smallest. Then the
 * burst at five moments of its life, on plain dark ground. The top row is seen from the game's usual camera angle, the bottom
 * row from a low one turned a little, where the floor runs away from the eye. In each a grey figure stands in for the
 * character, a crate stands on the floor beside it (the burst must lie under it) and a post stands between the
 * character and the camera (it must hide the beam). Run it with "gradlew cardPreview" (see build.gradle). The real
 * floor and the real shapes of things are the overlay's business and need the game to see.
 */
public final class CardPreview
{
	private static final long[] MOMENTS = {80, 250, 500, 1500, 3200};
	private static final int COLUMN = 330;
	private static final int ROW = 380;
	// The stand-in character's head, as corners round a middle (the last corner)
	private static final int HEAD_SIDES = 10;

	public static void main(String[] args) throws Exception
	{
		String out = args.length > 0 ? args[0] : "build/cards.png";
		String sprite = args.length > 1 ? args[1] : "";
		Season season = args.length > 2 && !args[2].isEmpty() ? Season.valueOf(args[2].toUpperCase()) : Season.NONE;
		Burst.Glow glow = args.length > 3 && !args[3].isEmpty() ? Burst.Glow.valueOf(args[3].toUpperCase()) : BeamColour.BY_HOLIDAY.glow(season);

		DropCard.Drop drop = new DropCard.Drop(DropCard.Kind.INSANE, "Avernic defender hilt");
		DropCard.Drop logged = new DropCard.Drop(DropCard.Kind.COLLECTION_LOG, "Giant egg sac(full)");
		File file = new File(sprite);
		if (file.isFile())
		{
			// As the game hands an item's picture over: the sprite somewhere inside a 36 by 32 box
			BufferedImage item = ImageIO.read(file);
			BufferedImage box = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
			Graphics2D b = box.createGraphics();
			b.drawImage(item, (36 - item.getWidth()) / 2, (32 - item.getHeight()) / 2, null);
			b.dispose();
			drop.picture = box;
			logged.picture = box;
		}

		int left = Math.round(DropCard.WIDTH * 1.5f) + 40;
		BufferedImage image = new BufferedImage(left + COLUMN * MOMENTS.length, 2 * ROW, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = image.createGraphics();
		g.setColor(new Color(34, 40, 30));
		g.fillRect(0, 0, image.getWidth(), image.getHeight());
		DropCard.paintCard(g, 20, 24, 1f, drop, 1f);
		DropCard.paintCard(g, 20, 180, 1f, logged, 1f);
		String[] how = {"Hold Alt, then", "drag to move, drag an edge to resize,", "right-click to put it back"};
		DropCard.paintCard(g, 20, 400, 1.5f, drop, 1f);
		DropCard.paintUnlocked(g, 20, 400, DropCard.size(drop.kind, 1.5f), how, 20, 400);
		DropCard.paintCard(g, 20, 630, DropCard.SMALLEST, logged, 1f);
		DropCard.paintUnlocked(g, 20, 630, DropCard.size(logged.kind, DropCard.SMALLEST), how, 20, 0);
		for (int row = 0; row < 2; row++)
		{
			for (int i = 0; i < MOMENTS.length; i++)
			{
				int footX = left + COLUMN * i + COLUMN / 2;
				int footY = ROW * row + (row == 0 ? 250 : 270);
				Stage stage = row == 0 ? new Stage(footX, footY, 62, 27, 0, 12) : new Stage(footX, footY, 74, 11, 25, 7);
				Rectangle view = new Rectangle(left + COLUMN * i, ROW * row, COLUMN, ROW - 30);
				scene(g, stage, view, footX, footY, MOMENTS[i], season, glow);
				g.setColor(new Color(200, 200, 200));
				g.drawString(MOMENTS[i] + " ms", footX - 20, ROW * (row + 1) - 10);
			}
		}
		g.dispose();
		File target = new File(out);
		if (target.getParentFile() != null)
		{
			target.getParentFile().mkdirs();
		}
		ImageIO.write(image, "png", target);
		System.out.println("wrote " + target.getAbsolutePath());
	}

	private static void scene(Graphics2D target, Stage stage, Rectangle view, int footX, int footY, long age, Season season, Burst.Glow glow)
	{
		Graphics2D g = (Graphics2D) target.create();
		g.setClip(view);
		// What stands in the scene, far to near: the crate, the character, the post
		Stage.Box crate = stage.box(1.5, 0.7, 0.9, 0.8);
		Stage.Box post = stage.box(0.1, -1.7, 0.3, 2.4);
		int headY = footY - 90;
		int[] xs = new int[HEAD_SIDES + 5];
		int[] ys = new int[HEAD_SIDES + 5];
		int[] first = new int[HEAD_SIDES + 2];
		int[] second = new int[HEAD_SIDES + 2];
		int[] third = new int[HEAD_SIDES + 2];
		for (int k = 0; k < HEAD_SIDES; k++)
		{
			xs[k] = footX + (int) Math.round(9 * Math.cos(k * 2 * Math.PI / HEAD_SIDES));
			ys[k] = headY + 9 + (int) Math.round(9 * Math.sin(k * 2 * Math.PI / HEAD_SIDES));
			first[k] = HEAD_SIDES;
			second[k] = k;
			third[k] = (k + 1) % HEAD_SIDES;
		}
		xs[HEAD_SIDES] = footX;
		ys[HEAD_SIDES] = headY + 9;
		int body = HEAD_SIDES + 1;
		int[][] corners = {{-7, headY + 18}, {7, headY + 18}, {7, footY}, {-7, footY}};
		for (int k = 0; k < 4; k++)
		{
			xs[body + k] = footX + corners[k][0];
			ys[body + k] = corners[k][1];
		}
		first[HEAD_SIDES] = body;
		second[HEAD_SIDES] = body + 1;
		third[HEAD_SIDES] = body + 2;
		first[HEAD_SIDES + 1] = body;
		second[HEAD_SIDES + 1] = body + 2;
		third[HEAD_SIDES + 1] = body + 3;

		crate.draw(g, new Color(150, 104, 58));
		g.setColor(new Color(120, 120, 120));
		g.fillOval(footX - 9, headY, 18, 18);
		g.fillRect(footX - 7, headY + 18, 14, 72);
		post.draw(g, new Color(96, 100, 110));
		Burst.paint(g, view, stage, age, 1f, season, glow, cut ->
		{
			crate.cut(cut, false);
			cut.faces(xs, ys, xs.length, first, second, third, null, first.length, true);
			post.cut(cut, true);
		});
		g.dispose();
	}
}

